package cli

import (
	"context"
	"fmt"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/internal/coreapi"
)

// mirrorColumns is the human table/field view of a mirror: the scannable
// repo name, the clone URL you'd copy, and whether the upstream is
// private. The cluster is omitted — it's already embedded in the clone
// URL — and the wire model's internal ids are dropped entirely. The clone
// URL is synthesised from the mirror's coords (the form `git clone`
// accepts), since the list API doesn't return it.
var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}

func mirrorRow(m coreapi.Mirror) []string {
	repo := m.Owner + "/" + m.Repo
	cloneURL := fmt.Sprintf("entire://%s/gh/%s/%s", m.ClusterHost, m.Owner, m.Repo)
	private := "no"
	if m.IsPrivate.Or(false) {
		private = "yes"
	}
	return []string{repo, cloneURL, private}
}

// defaultClusterHost is the cluster the mirror commands target when the
// caller omits the <cluster-host> argument. A pragmatic single-region
// default for now — once multi-cluster selection lands this should come
// from config/context rather than a constant.
const defaultClusterHost = "aws-us-east-2.entire.io"

// clusterArg returns the cluster host from the optional second positional
// (after <github-url>), or defaultClusterHost when it was omitted.
func clusterArg(args []string) string {
	if len(args) > 1 {
		return args[1]
	}
	return defaultClusterHost
}

// newRepoMirrorCmd is the `entire repo mirror` subtree: manage EntireDB
// GitHub-mirror placements on a cluster. Mirrors the standalone entiredb
// CLI's `entire repo mirror` surface for the server-side half (create /
// list / get / remove). The local-clone rewrite (`mirror use`) is not
// ported — it's a git-config + git-remote-entire concern outside the
// control-plane API.
func newRepoMirrorCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "mirror",
		Short: "Manage GitHub-mirror placements on EntireDB clusters",
	}
	cmd.AddCommand(newRepoMirrorCreateCmd())
	cmd.AddCommand(newRepoMirrorListCmd())
	cmd.AddCommand(newRepoMirrorGetCmd())
	cmd.AddCommand(newRepoMirrorRemoveCmd())
	return cmd
}

func newRepoMirrorCreateCmd() *cobra.Command {
	var (
		noWait      bool
		waitTimeout time.Duration
	)
	cmd := &cobra.Command{
		Use:   "create <github-url> [cluster-host]",
		Short: "Register a GitHub mirror on a cluster",
		Long: "Registers a mirror placement for a GitHub repo on the target " +
			"cluster, then waits for the initial GitHub→EntireDB clone to " +
			"finish so `git clone` works on return. Pass --no-wait to return " +
			"as soon as the placement is registered. Idempotent on " +
			"(upstream, cluster). The cluster-host defaults to " +
			defaultClusterHost + " when omitted.",
		Example: "  entire repo mirror create github.com/octocat/hello-world\n" +
			"  entire repo mirror create github.com/octocat/hello-world eu-west-1.entire.io",
		Args: cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			owner, repo, err := parseGitHubURL(args[0])
			if err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid <github-url>: %w", err)
			}
			clusterHost := clusterArg(args)
			return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
				created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
					Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
					Owner:       owner,
					Repo:        repo,
					ClusterHost: clusterHost,
				})
				if err != nil {
					return err
				}
				out := cmd.OutOrStdout()
				if created.Created {
					fmt.Fprintf(out, "Registered mirror %s\n", created.MirrorId)
				} else {
					fmt.Fprintf(out, "Mirror already exists (%s)\n", created.MirrorId)
				}
				fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
				if noWait {
					fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
					return nil
				}
				if err := waitForMirrorClone(ctx, out, clusterHost, owner, repo, waitTimeout); err != nil {
					return err
				}
				fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
				return nil
			})
		},
	}
	cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
	cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
	return cmd
}

func newRepoMirrorListCmd() *cobra.Command {
	var cluster, provider, owner string
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List mirrors you can see",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
				var params coreapi.ListMirrorsParams
				if cluster != "" {
					params.Cluster = coreapi.NewOptString(cluster)
				}
				if provider != "" {
					params.Provider = coreapi.NewOptString(provider)
				}
				if owner != "" {
					params.Owner = coreapi.NewOptString(owner)
				}
				out, err := c.ListMirrors(ctx, params)
				if err != nil {
					return nil, err
				}
				return out.Mirrors, nil
			})
		},
	}
	cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
	cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
	cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
	return cmd
}

func newRepoMirrorGetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "get <mirror-id>",
		Short: "Show a mirror by ULID",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runCoreObject(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) (*coreapi.Mirror, error) {
				sc, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: args[0]})
				if err != nil {
					return nil, err
				}
				return sc, nil
			})
		},
	}
}

func newRepoMirrorRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove <github-url> [cluster-host]",
		Short: "Un-register a GitHub mirror from a cluster",
		Long: "Removes a mirror placement for a GitHub repo from the target " +
			"cluster. Other clusters' placements of the same upstream are " +
			"unaffected. The cluster-host defaults to " + defaultClusterHost +
			" when omitted.",
		Example: "  entire repo mirror remove github.com/octocat/hello-world",
		Args:    cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			owner, repo, err := parseGitHubURL(args[0])
			if err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid <github-url>: %w", err)
			}
			clusterHost := clusterArg(args)
			return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
				// Delete by upstream coords in one call. A 404 is a real
				// error here, not idempotent success: the server only
				// answers 204 when it actually removed a placement, so a
				// 404 ("no such mirror / not visible / different cluster")
				// surfaces verbatim via renderCoreError rather than being
				// reported as a successful removal.
				if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
					Provider:    coreapi.DeleteMirrorProviderGithub,
					Owner:       owner,
					Repo:        repo,
					ClusterHost: clusterHost,
				}); err != nil {
					return err
				}
				cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
				return nil
			})
		},
	}
}

package auth

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"

	"github.com/entireio/auth-go/sts"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// repoExchangeTransportForTest, when non-nil, is used as the sts.Client
// transport by RepoScopedToken instead of the default. Test-only seam so
// the wire form (audience / scope / client_id) can be asserted without a
// live core. Production leaves it nil.
var repoExchangeTransportForTest http.RoundTripper

// SetRepoExchangeTransportForTest installs rt as the transport used by
// RepoScopedToken and returns a cleanup function. Test-only.
func SetRepoExchangeTransportForTest(rt http.RoundTripper) func() {
	prev := repoExchangeTransportForTest
	repoExchangeTransportForTest = rt
	return func() { repoExchangeTransportForTest = prev }
}

// RepoScopedToken exchanges the logged-in user's token for a short-lived,
// repo-scoped access token usable against a data-plane cluster's git
// endpoints (clone / fetch / info-refs).
//
// The data plane's git gate rejects the raw login bearer (HTTP 403): it
// only accepts a token whose RFC 8693 audience is <clusterBaseURL><repoSlug>
// and whose scope is "repo:<action>". This is the same exchange
// git-remote-entire performs internally for the entire:// transport — the
// CLI does it in-process when it needs to read the data plane directly
// (e.g. probing a mirror's clone readiness).
//
//   - clusterBaseURL is the data-plane cluster origin (scheme+host, e.g.
//     https://aws-us-east-2.entire.io); a trailing slash is trimmed.
//   - repoSlug is the full surface-prefixed path (e.g. /gh/octocat/hello
//     or /et/<project>/<repo>), joined to the cluster URL verbatim to form
//     the audience.
//   - action is "pull" for reads or "push" for writes.
//
// The exchange targets the same core endpoint and client identity the CLI
// logged in against (AuthBaseURL + the provider's STS path, client_id
// entire-cli), so a successful login implies a usable exchange. Errors
// surface verbatim from the STS endpoint (e.g. invalid_target when no
// mirror matches the slug+cluster).
//
// The subject token is the stored login access token read directly,
// rather than routed through the refresh-aware tokenmanager. That's
// deliberate for two reasons: (1) `entire login` (device flow) stores only
// a bare access token — no refresh token — so there is nothing the manager
// could refresh that this path can't equally use; an expired login token
// fails both ways. (2) The manager's exchange also emits an RFC 8693
// `resource` parameter alongside `audience`, whereas the data-plane gate
// keys solely on `audience`; going direct keeps the wire form byte-for-byte
// what git-remote-entire (and the standalone entiredb CLI) already send.
// Each call performs a fresh exchange and does not cache — callers that
// poll (e.g. the mirror clone wait) re-invoke on token expiry. If the CLI
// gains refresh tokens, route this through the tokenmanager instead.
func RepoScopedToken(ctx context.Context, clusterBaseURL, repoSlug, action string) (string, error) {
	provider := CurrentProvider()
	if strings.TrimSpace(provider.STSPath) == "" {
		return "", errors.New("repo-scoped token exchange requires a v2 auth host (set ENTIRE_AUTH_BASE_URL to a core that exposes /oauth/token)")
	}

	loginJWT, err := LookupCurrentToken()
	if err != nil {
		return "", fmt.Errorf("read login token: %w", err)
	}
	if loginJWT == "" {
		return "", ErrNotLoggedIn
	}

	clusterBaseURL = strings.TrimRight(clusterBaseURL, "/")
	if clusterBaseURL == "" {
		return "", errors.New("repo-scoped token exchange requires a target cluster URL")
	}
	issuer := api.AuthBaseURL()

	client := &sts.Client{
		Transport:         repoExchangeTransportForTest,
		BaseURL:           issuer,
		Path:              provider.STSPath,
		UserAgent:         provider.ClientID,
		AllowInsecureHTTP: isLoopbackHTTP(issuer) || insecureHTTPOverride.Load(),
	}
	set, err := client.Exchange(ctx, sts.ExchangeRequest{
		SubjectToken:     loginJWT,
		SubjectTokenType: sts.SubjectTokenTypeAccessToken,
		// sts.Client (unlike the tokenmanager) applies no default, so set
		// requested_token_type explicitly to the access-token URI.
		RequestedTokenType: sts.SubjectTokenTypeAccessToken,
		// Audience-only (no Resource): the data plane's git gate keys its
		// repo check on the audience host+slug. Sending a separate resource
		// param risks the server validating a different value than it grants.
		Audience: clusterBaseURL + repoSlug,
		Scope:    "repo:" + action,
		// Public-client identification per RFC 6749 §2.3.1, carried via
		// Extra because the sts package is provider-agnostic.
		Extra: url.Values{"client_id": {provider.ClientID}},
	})
	if err != nil {
		return "", fmt.Errorf("repo-scoped token exchange: %w", err)
	}
	return set.AccessToken, nil
}

